head.script:
scwin.callPopupCloseByOpener = function() {
	var rowJSON = {
		"addr": "서울시",
		"name": "손예진",
		"rowStatus": "R"
	};
	var dataObject = {
		type: "json",
		data: rowJSON,
		name: "rowObj"
	};
	var node = WebSquare.ModelUtil.findInstanceNode("vector");
	WebSquare.uiplugin.popup.openPopup("/sample/common_link/p_popupName_WEF-143_(WSQ-2144)_Zipcode.xml", {
		id: "pop1",
		type: "window",
		width: "400px",
		height: "400px",
		top: "200px",
		left: "200px",
		popupName: "pop2",
		modal: false,
		useIFrame: true,
		style: "",
		resizable: false,
		status: false,
		menubar: false,
		scrollbars: false,
		title: false,
		xml: node,
		srcData: "",
		destData: "",
		dataObject: dataObject,
		useATagBtn: (isUseATagBtn) ? "true" : "false"
	});
}
scwin.__isTag = function(id, tag) {
	var nodeName = document.getElementById(id).nodeName;
	return nodeName == tag;
}
scwin.__setUseATagBtn = function(fLag) {
	isUseATagBtn = fLag;
}
scwin.checkVal = function() {
	return scwin.__setUseATagBtn(false);
}
scwin.onpageload = function() {
	imports("uiplugin.popup");
	window.isUseATagBtn = true;
}
